300		for i, a := range addrs {
301			if i > 0 && a <= prev {
302				return false
303			}
304			prev = a
305			u, err := url.Parse(a)
306			if err != nil {
307				return false
308			}
309			if u.Scheme != "http" && u.Scheme != "https" {
310				return false
311			}
312			if u.Hostname() == "" || u.User != nil {
313				return false
314			}
315			// A literal '#' starts a fragment; reject even an empty one.
316			if strings.Contains(a, "#") {
317				return false
318			}
319		}
320		return true
