240		referenced := make(map[string]bool, len(*doc.Root.Chunks))
241		for _, c := range *doc.Root.Chunks {
242			referenced[c] = true
243		}
244		seen := make(map[string]bool, len(*doc.Blocks))
245		for _, b := range *doc.Blocks {
246			if seen[*b.CID] {
247				return integrity()
248			}
249			seen[*b.CID] = true
250			if !referenced[*b.CID] {
251				return integrity()
252			}
253		}
254		for c := range referenced {
255			if !seen[c] {
256				return integrity()
257			}
258		}
259	
260		// Every block identifier must be the digest of its decoded bytes.
261		for cid, data := range blockData {
262			if chunkCID(data) != cid {
263				return integrity()
264			}
265		}
266	
267		// Rebuild the body in manifest order under the fixed chunking rules:
268		// every chunk but the last is exactly ChunkSize, the last is 1..ChunkSize,
269		// and an empty object carries no chunks at all.
270		chunks := *doc.Root.Chunks
271		if size == 0 && len(chunks) != 0 {
272			return integrity()
273		}
274		if size > 0 && len(chunks) == 0 {
275			return integrity()
276		}
277		total := 0
278		for i, c := range chunks {
279			n := len(blockData[c])
280			if i < len(chunks)-1 {
281				if n != ChunkSize {
282					return integrity()
283				}
284			} else if n < 1 || n > ChunkSize {
285				return integrity()
286			}
287			total += n
288		}
289		if total > MaxObjectSize {
290			return nil, "payload_too_large", http.StatusRequestEntityTooLarge
291		}
292		if total != size {
293			return integrity()
294		}
295		if rootCID(size, chunks) != *doc.Root.CID {
296			return integrity()
297		}
298	
299		obj = &object{
300			cid:    *doc.Root.CID,
301			size:   size,
302			chunks: make([][]byte, 0, len(chunks)),
303			cids:   append([]string{}, chunks...),
304		}
305		for _, c := range chunks {
306			obj.chunks = append(obj.chunks, blockData[c])
307		}
308		return obj, "", 0
