311	// wellFormedJSON reports whether data is a single well-formed JSON value
312	// with no duplicate object keys and nothing but whitespace after it.
313	func wellFormedJSON(data []byte) bool {
314		dec := json.NewDecoder(bytes.NewReader(data))
315		var walk func() bool
316		walk = func() bool {
317			tok, err := dec.Token()
318			if err != nil {
319				return false
320			}
321			delim, ok := tok.(json.Delim)
322			if !ok {
323				return true
324			}
325			switch delim {
326			case '{':
327				seen := make(map[string]bool)
328				for dec.More() {
329					key, err := dec.Token()
330					if err != nil {
331						return false
332					}
333					name, ok := key.(string)
334					if !ok || seen[name] {
335						return false
336					}
337					seen[name] = true
338					if !walk() {
339						return false
340					}
341				}
342				_, err := dec.Token()
343				return err == nil
344			case '[':
345				for dec.More() {
346					if !walk() {
347						return false
348					}
349				}
350				_, err := dec.Token()
351				return err == nil
352			}
353			return false
354		}
355		if !walk() {
356			return false
357		}
358		_, err := dec.Token()
359		return err == io.EOF
360	}
361	
362	// parseInt converts a raw JSON value to an int, rejecting strings,
363	// non-numeric literals and fractional values as syntax errors.
364	func parseInt(raw json.RawMessage) (int, error) {
365		if len(raw) == 0 || raw[0] == '"' {
366			return 0, strconv.ErrSyntax
367		}
368		v, err := strconv.ParseInt(string(raw), 10, 0)
369		if err != nil {
370			return 0, err
371		}
372		return int(v), nil
373	}
