const retrievalTimeout = 30 * time.Second

// retrievalResponse is the JSON body of POST /v1/retrievals/{cid}. It extends
// the upload response with the provider and address that supplied the body;
// both are null when the object was already stored locally.
type retrievalResponse struct {
    CID        string   `json:"cid"`
    Size       int      `json:"size"`
    ChunkSize  int      `json:"chunkSize"`
    Chunks     []string `json:"chunks"`
    Created    bool     `json:"created"`
    ProviderID *string  `json:"providerId"`
    Address    *string  `json:"address"`
}

// retriever fetches missing objects from the provider directory.
type retriever struct {
    objects   *store
    providers *providerDirectory
    client    *http.Client
}

func newRetriever(objects *store, providers *providerDirectory) *retriever {
    return &retriever{
        objects:   objects,
        providers: providers,
        client: &http.Client{
            Timeout: retrievalTimeout,
            CheckRedirect: func(_ *http.Request, _ []*http.Request) error {
                return http.ErrUseLastResponse
            },
        },
    }
}

// postRetrieval handles POST /v1/retrievals/{cid}.
func (rv *retriever) postRetrieval(w http.ResponseWriter, r *http.Request) {
